def current_rows(events):
    latest = {}
    for ev in events:
        eid = ev['id']
        key = (ev['event_time'], ev['seq'])
        if eid not in latest or key > latest[eid][:2]:
            latest[eid] = (ev['event_time'], ev['seq'], ev['op'], ev['value'])
    result = []
    for eid in sorted(latest.keys()):
        _, _, op, value = latest[eid]
        if op != 'D':
            result.append({'id': eid, 'value': value})
    return result
