def schema_drift(expected, actual):
    def collect_leaves(subtree, prefix):
        result = []
        for key, value in subtree.items():
            path = f"{prefix}.{key}" if prefix else key
            if isinstance(value, dict):
                result.extend(collect_leaves(value, path))
            else:
                result.append(path)
        return result

    def compare(exp, act, prefix=""):
        differences = []
        all_keys = set(exp.keys()) | set(act.keys())
        for key in all_keys:
            path = f"{prefix}.{key}" if prefix else key
            if key not in act:
                differences.extend(collect_leaves(exp[key], path))
                continue
            if key not in exp:
                differences.extend(collect_leaves(act[key], path))
                continue
            # both present
            if isinstance(exp[key], dict) and isinstance(act[key], dict):
                differences.extend(compare(exp[key], act[key], path))
            else:
                if exp[key] != act[key]:
                    differences.append(path)
        return differences

    return sorted(compare(expected, actual))
