def committable_windows(events, watermark):
    """
    Returns a dictionary mapping window to a list of values from events that
    have event_time > watermark, preserving input order and first-seen window order.
    """
    result = {}
    for event in events:
        if event['event_time'] > watermark:
            window = event['window']
            if window not in result:
                result[window] = []
            result[window].append(event['value'])
    return result
